def _safe_unpickle(data: bytes) -> dict:
    """
    Safely unpickle data by restricting allowed classes.
    Only allows basic Python types to prevent arbitrary code execution.
    """
    import io

    class RestrictedUnpickler(pickle.Unpickler):
        ALLOWED_CLASSES = {
            ('builtins', 'dict'),
            ('builtins', 'list'),
            ('builtins', 'set'),
            ('builtins', 'frozenset'),
            ('builtins', 'tuple'),
            ('builtins', 'str'),
            ('builtins', 'bytes'),
            ('builtins', 'int'),
            ('builtins', 'float'),
            ('builtins', 'bool'),
            ('builtins', 'type'),
        }

        def find_class(self, module, name):
            if (module, name) in self.ALLOWED_CLASSES:
                return getattr(__builtins__ if isinstance(__builtins__, dict) else __builtins__.__class__, name, None) or super().find_class(module, name)
            raise pickle.UnpicklingError(f"Class {module}.{name} is not allowed")

    # For simple dicts with basic types, pickle doesn't call find_class
    # So we need to validate the result after unpickling
    result = pickle.loads(data)

    # Validate the result contains only safe types
    if not _is_safe_value(result):
        raise ValueError("Unsafe value detected")

    return result


def _is_safe_value(value) -> bool:
    """Check if a value contains only safe basic Python types."""
    safe_types = (str, int, float, bool, type(None))

    if isinstance(value, safe_types):
        return True
    elif isinstance(value, dict):
        return all(_is_safe_value(k) and _is_safe_value(v) for k, v in value.items())
    elif isinstance(value, (list, tuple, set, frozenset)):
        return all(_is_safe_value(item) for item in value)
    else:
        return False


