class RestrictedUnpickler(pickle.Unpickler):
    """A restricted unpickler that only allows safe types."""

    SAFE_BUILTINS = frozenset({'dict', 'list', 'set', 'frozenset', 'tuple', 'str', 'int', 'float', 'bool', 'bytes', 'type', 'NoneType'})

    def find_class(self, module, name):
        # Only allow safe builtins
        if module == "builtins" and name in self.SAFE_BUILTINS:
            return getattr(__builtins__ if isinstance(__builtins__, dict) else __builtins__.__class__, name, None) or getattr(pickle, name, None)
        # Reject everything else
        raise pickle.UnpicklingError(f"Forbidden class: {module}.{name}")


def restricted_loads(data: bytes) -> dict:
    """Safely load pickled data with restrictions on allowed types."""
    return RestrictedUnpickler(io.BytesIO(data)).load()


