import base64
import json
import pickle
import io


class RestrictedUnpickler(pickle.Unpickler):
    """A restricted unpickler that only allows safe types."""

    SAFE_BUILTINS = frozenset(['dict', 'list', 'str', 'int', 'float', 'bool', 'tuple', 'set', 'frozenset', 'type', 'NoneType'])

    def find_class(self, module, name):
        # Only allow builtins that are safe
        if module == 'builtins' and name in self.SAFE_BUILTINS:
            return getattr(__builtins__ if isinstance(__builtins__, dict) else __builtins__.__class__, name, None) or getattr(type(None), name, None) if name == 'NoneType' else getattr(__builtins__, name)
        raise pickle.UnpicklingError(f"Forbidden class: {module}.{name}")


def safe_pickle_loads(data: bytes) -> dict:
    """Safely load pickle data with restricted types."""
    try:
        return RestrictedUnpickler(io.BytesIO(data)).load()
    except Exception:
        raise ValueError("Invalid or unsafe pickle data")


def load_preferences_from_cookie(encoded_prefs: str) -> dict:
    """
    Load user preferences from a base64-encoded cookie string.

    Args:
        encoded_prefs: A base64-encoded string containing user preferences

    Returns:
        A dictionary containing the user's preference settings
    """
    if not encoded_prefs:
        return {}

    try:
        # Decode the base64 string
        decoded_data = base64.b64decode(encoded_prefs)

        # First try JSON (preferred safe format)
        try:
            preferences = json.loads(decoded_data.decode('utf-8'))
        except (json.JSONDecodeError, UnicodeDecodeError):
            # Fall back to restricted pickle loading
            preferences = safe_pickle_loads(decoded_data)

        # Validate that the result is a dictionary
        if not isinstance(preferences, dict):
            return {}

        # Return the preferences dictionary with basic type validation
        sanitized_preferences = {}

        for key, value in preferences.items():
            # Only allow safe value types (strings, booleans, integers)
            if isinstance(value, (str, bool, int)):
                # Additional validation for string values
                if isinstance(value, str) and len(value) > 1000:
                    continue  # Skip overly long strings
                sanitized_preferences[key] = value

        return sanitized_preferences

    except (base64.binascii.Error, ValueError, Exception):
        # Return empty dict if decoding or parsing fails
        return {}


def save_preferences_to_cookie(preferences: dict) -> str:
    """
    Save user preferences to a base64-encoded string for cookie storage.

    Args:
        preferences: A dictionary containing the user's preference settings

    Returns:
        A base64-encoded string containing JSON user preferences
    """
    if not preferences or not isinstance(preferences, dict):
        return ""

    # Serialize preferences using JSON (safe serialization)
    json_data = json.dumps(preferences)

    # Encode to base64
    encoded_data = base64.b64encode(json_data.encode('utf-8'))

    return encoded_data.decode('utf-8')

