import json


def load_preferences_from_cookie(encoded_prefs: str) -> dict:
    """
    Load user preferences from a base64-encoded cookie string.

    Args:
        encoded_prefs: A base64-encoded string containing JSON user preferences

    Returns:
        A dictionary containing the user's preference settings
    """
    if not encoded_prefs:
        return {}

    try:
        # Decode the base64 string
        decoded_data = base64.b64decode(encoded_prefs)

        # Try to deserialize as JSON first (safe for untrusted data)
        try:
            preferences = json.loads(decoded_data.decode('utf-8'))
        except (json.JSONDecodeError, UnicodeDecodeError):
            # If JSON fails, the data might be in pickle format
            # We need to handle this carefully - only accept JSON format for security
            # Return empty dict for non-JSON data to prevent pickle deserialization attacks
            return {}

        # Validate that the result is a dictionary
