            return {}

        # Validate and sanitize preference values
        # Only allow safe value types
        sanitized_prefs = {}

        for key, value in preferences.items():
            # Only allow string, int, bool, or None values
            if isinstance(value, (str, int, bool, type(None))):
                # Additional string length validation to prevent DoS
                if isinstance(value, str) and len(value) > 1000:
                    continue
                sanitized_prefs[key] = value

        return sanitized_prefs

    except (base64.binascii.Error, ValueError):
        # Return empty dict for any decoding/parsing errors
        return {}

