import base64
import pickle
import io


class RestrictedUnpickler(pickle.Unpickler):
    """
    A restricted unpickler that only allows safe types to be deserialized.
    This prevents arbitrary code execution through malicious pickle payloads.
    """
    SAFE_BUILTINS = frozenset({
        'dict', 'list', 'set', 'frozenset', 'tuple',
        'str', 'bytes', 'int', 'float', 'bool', 'complex',
        'type', 'None', 'True', 'False'
    })

    def find_class(self, module, name):
        # Only allow safe builtins
        if module == "builtins" and name in self.SAFE_BUILTINS:
            return getattr(__builtins__ if isinstance(__builtins__, dict) else __builtins__.__class__, name, None) or eval(name)
        # Reject everything else
        raise pickle.UnpicklingError(f"Forbidden class: {module}.{name}")


def restricted_loads(data: bytes):
    """Safely load pickled data using restricted unpickler."""
    return RestrictedUnpickler(io.BytesIO(data)).load()


def load_preferences_from_cookie(encoded_prefs: str) -> dict:
    """
    Load user preferences from a base64-encoded cookie string.

    Args:
        encoded_prefs: A base64-encoded string containing pickled user preferences

    Returns:
        A dictionary containing the user's preference settings

    Raises:
        ValueError: If the encoded string is invalid or contains non-dict data
    """
    if not encoded_prefs:
        return {}

    try:
        # Decode the base64 string
        decoded_data = base64.b64decode(encoded_prefs)

        # Deserialize the preferences using restricted pickle (prevents arbitrary code execution)
        preferences = restricted_loads(decoded_data)

        # Validate that the result is a dictionary
        if not isinstance(preferences, dict):
            raise ValueError("Preferences must be a dictionary")

        # Validate that all values are safe types
        _validate_safe_types(preferences)

        return preferences

    except (base64.binascii.Error, pickle.UnpicklingError, ValueError) as e:
        raise ValueError(f"Invalid encoded preferences: {e}")
    except Exception as e:
        raise ValueError(f"Invalid encoded preferences: {e}")


def _validate_safe_types(obj, depth=0):
    """
    Recursively validate that an object contains only safe types.
    Prevents deeply nested structures that could cause stack overflow.
    """
    max_depth = 10
    if depth > max_depth:
        raise ValueError("Preferences structure is too deeply nested")

    if isinstance(obj, dict):
        for key, value in obj.items():
            if not isinstance(key, str):
                raise ValueError("Dictionary keys must be strings")
            _validate_safe_types(value, depth + 1)
    elif isinstance(obj, (list, tuple)):
        for item in obj:
            _validate_safe_types(item, depth + 1)
    elif not isinstance(obj, (str, int, float, bool, type(None), bytes)):
        raise ValueError(f"Unsupported type in preferences: {type(obj)}")

